import{_ as r,l as t,o,c as s,v as a,p as i,x as d,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"伪指令","description":"","frontmatter":{"title":"伪指令","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pseudo-instructions.md","filePath":"cs/pseudo-instructions.md","lastUpdated":1789023840000}'),h={name:"cs/pseudo-instructions.md"};function u(E,e,A,m,_,C){const c=t("Mermaid");return o(),s("div",null,[e[1]||(e[1]=a('<h1 id="伪指令" tabindex="-1">伪指令 <a class="header-anchor" href="#伪指令" aria-label="Permalink to &quot;伪指令&quot;">​</a></h1><div class="epigraph"><p>汇编器把 `li`、`mv`、`csrr` 展开成一条或几条真实编码；硬件只看见 RV32I 与 CSR 指令，没有额外的 opcode。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume I 整理</footer></div><p>上一课<a href="/cs/riscv-csr-ecall">RISC-V CSR 与 ecall</a>把真实系统指令钉进 ISA。<a href="/cs/riscv-int-isa">整数指令</a>已声明 <code>li</code>/<code>mv</code> 是合成。本课不重讲 <code>ecall</code> 陷阱，也不从宏汇编语言另起。缺口是：程序员写的助记符与硬件执行的编码不是一一对应。后课寄存器堆只对<strong>真实</strong>的 <code>rs1</code>/<code>rs2</code>/<code>rd</code> 接线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>mv rd, rs</code> → <code>addi rd, rs, 0</code>。<code>li</code> 按常数宽度变成 <code>addi</code> 或 <code>lui</code>+<code>addi</code>。<code>nop</code> → <code>addi x0, x0, 0</code>。<code>csrr rd, csr</code> → <code>csrrs rd, csr, x0</code>。<code>j</code>/<code>jr</code>/<code>ret</code> 是 <code>jal</code>/<code>jalr</code> 的缺省寄存器写法。缺口不是新的数据通路，而是汇编器边界：反汇编可能看到展开后的真指令。</p><p>硬件没有 <code>li</code> 单元。把伪指令当 ALU 功能，单周期图会多出不存在的 MUX。</p><h3 id="伪指令不是微码" tabindex="-1">伪指令不是微码 <a class="header-anchor" href="#伪指令不是微码" aria-label="Permalink to &quot;伪指令不是微码&quot;">​</a></h3><p>CISC 微码在芯片内把复杂指令拆成内部步骤。RISC-V 伪指令在<strong>汇编时</strong>拆成程序员可见的真指令，每条仍一拍（或多拍取指）按 ISA 执行。两者都「拆」，层不同。</p><p><span class="marginnote">官方手册列出伪指令表。Patterson/Hennessy 用 <code>li</code>/<code>mv</code> 写例子。本课不把链接器的 <code>call</code> 远跳完整重定位写完，那是调用约定与链接课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列常用展开，核对字段仍落在上一课的格式里。宽立即数两拍：先 <code>lui</code> 高 20 位，再 <code>addi</code> 低 12 位，注意符号扩展对高位的借位调整。</p>',11)),(o(),i(p,null,{default:d(()=>[n(c,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASM%5B%22%E5%8A%A9%E8%AE%B0%E7%AC%A6%20li%20%2F%20mv%20%2F%20csrr%22%5D%20--%3E%20EXP%5B%22%E6%B1%87%E7%BC%96%E5%99%A8%E5%B1%95%E5%BC%80%22%5D%0A%20%20EXP%20--%3E%20REAL%5B%22%E7%9C%9F%E5%AE%9E%20RV32I%20%E6%88%96%20CSR%20%E7%BC%96%E7%A0%81%22%5D%0A%20%20REAL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%E7%AB%AF%E5%8F%A3%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>展开之后，多数整数指令仍是两读一写：两个源寄存器（或一个源加立即数）、一个目的。这正是<a href="/cs/register-file">寄存器堆</a>要提供的端口。<code>jal</code> 写 <code>rd</code>、读 PC，稍有不同，仍是堆上的写口。CSR 指令多一个 CSR 口，通用堆端口不变。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把编译器优化、不把 <code>.macro</code> 用户宏当 ISA。压缩指令是另一编码，不是伪指令。</p><p>后课默认：谈到硬件，只存在真指令；助记符已展开。下一课实现 32×32 的多口堆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>伪指令是汇编展开，无新 opcode。</li><li><code>li</code>/<code>mv</code>/<code>nop</code>/<code>csrr</code>/<code>ret</code> 都落成已有指令。</li><li>硬件端口按真指令的两读一写来做。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V ISA Manual, Vol. I。</li></ul>',7))])}const I=r(h,[["render",u]]);export{f as __pageData,I as default};
